最小代码
val toastChannel = eventChannel<String>("ui.toast")
toastChannel.post("保存成功")
collectEvent(toastChannel.flow()) {
 showToast(it)
}

最小代码
viewModel.startSyncCase()
DefaultFlowBus.flow<WorkerSyncLog>().collect { event ->
 if (event.scopeName == viewModel.currentScopeName()) render(event.message)
}
